<?php
declare(strict_types=1);require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/_helper.php';perpus_require_manage();$bukuId=(int)($_GET['buku_id']??$_POST['buku_id']??0);$error='';$flash=perpus_flash();$st=$pdo->prepare('SELECT * FROM perpustakaan_buku WHERE id=?');$st->execute([$bukuId]);$b=$st->fetch();if(!$b)exit('Buku tidak ditemukan.');
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$action=$_POST['action']??'';try{$pdo->beginTransaction();if($action==='generate'){$jumlah=(int)($_POST['jumlah']??0);if($jumlah<1||$jumlah>500)throw new RuntimeException('Jumlah tambahan harus 1 sampai 500.');$st=$pdo->prepare('SELECT kode_eksemplar FROM perpustakaan_eksemplar WHERE buku_id=? ORDER BY id DESC LIMIT 1');$st->execute([$bukuId]);$last=(string)($st->fetchColumn()??'');$n=$last!==''?(int)substr($last,strrpos($last,'-')+1):0;$ins=$pdo->prepare('INSERT INTO perpustakaan_eksemplar(buku_id,kode_eksemplar,kondisi,status,lokasi) VALUES(?,?,?,?,?)');for($i=1;$i<=$jumlah;$i++){$n++;$ins->execute([$bukuId,$b['kode_buku'].'-'.str_pad((string)$n,4,'0',STR_PAD_LEFT),'baik','tersedia',$b['lokasi']?:null]);}perpus_sync_stock($pdo,$bukuId);perpus_audit_detail($pdo,'CREATE',$bukuId,'Menambah '.$jumlah.' eksemplar untuk '.$b['kode_buku'],[],['jumlah_ditambah'=>$jumlah]);perpus_flash($jumlah.' eksemplar ditambahkan.');}elseif($action==='update'){ $changes=[]; foreach((array)($_POST['status']??[]) as $id=>$status){$id=(int)$id;if(!in_array($status,['tersedia','rusak','hilang','nonaktif'],true))continue;$q=$pdo->prepare('SELECT kode_eksemplar,status,kondisi FROM perpustakaan_eksemplar WHERE id=? AND buku_id=? FOR UPDATE');$q->execute([$id,$bukuId]);$before=$q->fetch();if(!$before||$before['status']==='dipinjam')continue;$pdo->prepare('UPDATE perpustakaan_eksemplar SET status=? WHERE id=? AND buku_id=? AND status<>\'dipinjam\'')->execute([$status,$id,$bukuId]);$changes[]=['kode'=>$before['kode_eksemplar'],'before_status'=>$before['status'],'after_status'=>$status,'kondisi'=>$before['kondisi']];} perpus_sync_stock($pdo,$bukuId);perpus_audit_detail($pdo,'UPDATE',$bukuId,'Memperbarui status eksemplar',[],['changes'=>$changes]);perpus_flash('Status eksemplar diperbarui.');}$pdo->commit();redirect('perpustakaan/eksemplar.php?buku_id='.$bukuId);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$st=$pdo->prepare('SELECT * FROM perpustakaan_eksemplar WHERE buku_id=? ORDER BY id');$st->execute([$bukuId]);$rows=$st->fetchAll();$page_title='Eksemplar Buku';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main"><header class="topbar"><div class="topbar-title">Eksemplar Buku</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1><i class="bi bi-upc-scan"></i> Eksemplar</h1><p><strong><?=e($b['judul'])?></strong> · <?=e($b['kode_buku'])?> · setiap eksemplar memiliki QR unik.</p></div><div class="page-header-actions"><a class="btn btn-primary" href="<?=BASE_URL?>perpustakaan/buku_qr.php?buku_id=<?=$bukuId?>"><i class="bi bi-printer"></i> Cetak Semua QR</a><a class="btn btn-secondary" href="<?=BASE_URL?>perpustakaan/buku.php">Kembali</a></div></div><?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="form-card"><h5>Tambah Eksemplar</h5><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="buku_id" value="<?=$bukuId?>"><input type="hidden" name="action" value="generate"><div class="form-group"><label>Jumlah</label><input class="form-control" type="number" min="1" max="500" name="jumlah" value="1" required></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-plus-circle"></i> Buat Eksemplar + QR</button></div></form></div><div class="form-card"><form method="post"><?=csrf_field()?><input type="hidden" name="buku_id" value="<?=$bukuId?>"><input type="hidden" name="action" value="update"><div class="table-responsive"><table class="data-table"><thead><tr><th>QR / Kode Eksemplar</th><th>Kondisi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4" class="empty-state">Belum ada eksemplar.</td></tr><?php else:foreach($rows as $r):?><tr><td><strong><?=e($r['kode_eksemplar'])?></strong></td><td><?=e(ucwords(str_replace('_',' ',$r['kondisi'])))?></td><td><select class="form-control" name="status[<?=$r['id']?>]" <?=$r['status']==='dipinjam'?'disabled':''?>><?php foreach(['tersedia','rusak','hilang','nonaktif'] as $v):?><option value="<?=$v?>" <?=$r['status']===$v?'selected':''?>><?=e(ucwords($v))?></option><?php endforeach;?></select><?php if($r['status']==='dipinjam'):?><input type="hidden" name="status[<?=$r['id']?>]" value="dipinjam"><?php endif;?></td><td><a class="btn btn-sm btn-secondary" href="<?=BASE_URL?>perpustakaan/buku_qr.php?eksemplar_id=<?=$r['id']?>" title="Cetak QR"><i class="bi bi-qr-code"></i></a></td></tr><?php endforeach;endif;?></tbody></table></div><div class="form-actions"><button class="btn btn-primary" type="submit">Simpan Status</button></div></form></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';
